import "server-only";
import type { StyleSlug } from "@/lib/catalog";

/**
 * The example portrait for each style (our own sample, without name lettering). It is the template
 * the image model follows for everything except the dog itself: pose, head angle, crop, background,
 * medium and finish. The customer's photos supply only the dog's identity. JPEG, 768x960, base64.
 */
const REFS: Record<StyleSlug, string> = {
  "modern":
    "",
  "modern-sage":
    "",
  "watercolor":
    "",
  "fine-line":
    "",
  "pastel":
    "",
  "modern-oil":
    "",
  "charcoal":
    "",
};

/** The style reference image for a style, or null if there is none. */
export function styleReference(style: StyleSlug): { bytes: Buffer; mime: string } | null {
  const b64 = REFS[style];
  return b64 ? { bytes: Buffer.from(b64, "base64"), mime: "image/jpeg" } : null;
}
